INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d1d2d3d4-4401-4000-8000-000000000001', 'b1b2c3d4-4444-4000-8000-000000000004', 1, 'O Corpo Revela a Pessoa', 'Introdução à Teologia do Corpo', '{"text": "S\u00e3o Jo\u00e3o Paulo II dedicou 129 audi\u00eancias (1979\u20131984) a desenvolver uma vis\u00e3o revolucion\u00e1ria: o corpo humano n\u00e3o \u00e9 apenas mat\u00e9ria \u2014 \u00e9 uma teologia viva, uma linguagem que revela o mist\u00e9rio de Deus.\n\n**\"O corpo, e somente ele, \u00e9 capaz de tornar vis\u00edvel o que \u00e9 invis\u00edvel: o espiritual e o divino.\"** \u2014 S\u00e3o Jo\u00e3o Paulo II\n\nNo relato da cria\u00e7\u00e3o (Gn 1-2), encontramos tr\u00eas experi\u00eancias origin\u00e1rias:\n\n1. **Solid\u00e3o Original** \u2014 Ad\u00e3o percebe que \u00e9 diferente dos animais; possui autoconsci\u00eancia e liberdade.\n2. **Unidade Original** \u2014 \"Ser\u00e3o os dois uma s\u00f3 carne\" (Gn 2,24). O corpo foi feito para a comunh\u00e3o.\n3. **Nudez Original** \u2014 \"Estavam nus e n\u00e3o sentiam vergonha\" (Gn 2,25). A pureza do olhar antes do pecado.\n\nA Teologia do Corpo n\u00e3o \u00e9 apenas sobre sexualidade \u2014 \u00e9 sobre o significado de ser pessoa.", "scripture": "Gn 1,27 \u2014 Deus criou o ser humano \u00e0 sua imagem; \u00e0 imagem de Deus o criou; homem e mulher os criou."}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;